import * as THREE from 'three/webgpu';
import {
  mix,
  vec3,
  float,
  uv,
  step,
  smoothstep,
  min,
  max,
  multiply,
  add,
  sub,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createSDFMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(
    config.position?.[0] ?? 0,
    config.position?.[1] ?? 0,
    config.position?.[2] ?? 0
  );
  group.rotation.set(
    config.rotation?.[0] ?? 0,
    config.rotation?.[1] ?? 0,
    config.rotation?.[2] ?? 0
  );
  group.scale.set(
    config.scale?.[0] ?? 1,
    config.scale?.[1] ?? 1,
    config.scale?.[2] ?? 1
  );

  // ----- Button geometry -----
  const BUTTON_WIDTH = 2.6;
  const BUTTON_HEIGHT = 0.68;
  const geometry = new THREE.PlaneGeometry(BUTTON_WIDTH, BUTTON_HEIGHT, 1, 1);

  // ----- Gradient material (node based) -----
  const gradStops = [
    { at: 0.0, hex: '#ff4450' },
    { at: 0.55, hex: '#ff2a38' },
    { at: 1.0, hex: '#c1121f' },
  ];
  const colorA = new THREE.Color(gradStops[0].hex);
  const colorB = new THREE.Color(gradStops[1].hex);
  const colorC = new THREE.Color(gradStops[2].hex);
  const accentColor = new THREE.Color(config.colors?.accent ?? '#ff2a38');

  // node color gradient (vertical)
  const uvs = uv();
  const t = uvs.y;
  const mixAB = mix(vec3(colorA.r, colorA.g, colorA.b), vec3(colorB.r, colorB.g, colorB.b), smoothstep(float(gradStops[0].at), float(gradStops[1].at), t));
  const gradientColor = mix(mixAB, vec3(colorC.r, colorC.g, colorC.b), smoothstep(float(gradStops[1].at), float(gradStops[2].at), t));

  // edge emissive rim (approximate)
  const rimWidth = 0.02; // fraction of UV space
  const edgeDist = min(min(uvs.x, sub(float(1.0), uvs.x)), min(uvs.y, sub(float(1.0), uvs.y)));
  const rimMask = step(float(rimWidth), edgeDist);
  const emissiveNode = multiply(vec3(accentColor.r, accentColor.g, accentColor.b), float(1.6));
  const finalEmissive = multiply(emissiveNode, sub(float(1.0), rimMask)); // only rim emits

  const material = new THREE.MeshStandardNodeMaterial();
  material.colorNode = gradientColor;
  material.emissiveNode = finalEmissive;
  material.metalnessNode = float(0.35);
  material.roughnessNode = float(0.5);
  material.clearcoatNode = float(0.22);
  material.clearcoatRoughnessNode = float(0.1);
  material.side = THREE.DoubleSide;

  const buttonMesh = new THREE.Mesh(geometry, material);
  buttonMesh.castShadow = true;
  buttonMesh.receiveShadow = true;
  group.add(buttonMesh);

  // ----- Text label (CTA) -----
  const labelOptions = {
    fontSize: config.typography?.['cta-label']?.fontSize ?? 20,
    fontWeight: config.typography?.['cta-label']?.fontWeight ?? 700,
    letterSpacing: config.typography?.['cta-label']?.letterSpacing ?? 0.08,
    lineHeight: config.typography?.['cta-label']?.lineHeight ?? 1,
    color: config.colors?.ink ?? '#16161d',
    align: 'center',
    maxWidth: BUTTON_WIDTH - 0.5, // side padding
    fontFamily: config.typography?.['cta-label']?.family ?? 'JetBrains Mono',
  };
  const labelMesh = createSDFMesh('BEGIN COMMISSION', labelOptions, ctx.fontAtlas);
  labelMesh.position.set(0, 0, 0.01); // slight offset to avoid z‑fighting
  group.add(labelMesh);

  // ----- Caption text -----
  const captionOptions = {
    fontSize: config.typography?.caption?.fontSize ?? 9,
    fontWeight: config.typography?.caption?.fontWeight ?? 400,
    letterSpacing: config.typography?.caption?.letterSpacing ?? 0.12,
    lineHeight: config.typography?.caption?.lineHeight ?? 1.4,
    color: config.colors?.paper ?? '#e8ecf2',
    align: 'center',
    maxWidth: BUTTON_WIDTH,
    fontFamily: config.typography?.caption?.family ?? 'JetBrains Mono',
  };
  const captionMesh = createSDFMesh('NO DEPOSIT REQUIRED', captionOptions, ctx.fontAtlas);
  const captionOffsetY = -(BUTTON_HEIGHT / 2) - 0.25 - (captionOptions.fontSize / 100); // rough estimate
  captionMesh.position.set(0, captionOffsetY, 0.01);
  group.add(captionMesh);

  // ----- Interaction handlers storage -----
  group.userData.handlers = {};

  // ----- GSAP timelines for animations -----
  const timelines = [];

  // mount weighted‑settle animation (scale 1.04 → 1.0 over 0.9s)
  const settleTl = gsap.timeline({ paused: true });
  settleTl.fromTo(
    group.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  settleTl.play();
  timelines.push(settleTl);

  // hover animation (translateZ and emissive intensity)
  let hoverTl = null;
  group.userData.handlers.pointerenter = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(
      group.position,
      { z: 0.06, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
    );
    hoverTl.to(
      material,
      { emissiveIntensity: 2.2, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      0
    );
    timelines.push(hoverTl);
  };
  group.userData.handlers.pointerleave = () => {
    if (hoverTl) hoverTl.kill();
    const tl = gsap.timeline();
    tl.to(
      group.position,
      { z: 0, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
    );
    tl.to(
      material,
      { emissiveIntensity: 1.6, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      0
    );
    timelines.push(tl);
  };

  // press animation (scale 1.0 → 0.97)
  let pressTl = null;
  group.userData.handlers.pointerdown = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(
      group.scale,
      { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' }
    );
    timelines.push(pressTl);
    // deepen chamfer shadow not modeled; placeholder for future
  };
  group.userData.handlers.pointerup = () => {
    if (pressTl) pressTl.kill();
    const tl = gsap.timeline();
    tl.to(
      group.scale,
      { x: 1, y: 1, z: 1, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' }
    );
    timelines.push(tl);
  };

  // ----- Cleanup ----------
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    geometry.dispose();
    material.dispose();
    if (labelMesh && labelMesh.geometry) labelMesh.geometry.dispose();
    if (labelMesh && labelMesh.material) labelMesh.material.dispose();
    if (captionMesh && captionMesh.geometry) captionMesh.geometry.dispose();
    if (captionMesh && captionMesh.material) captionMesh.material.dispose();
  };

  // Apply any cinematic primitives listed (none in this spec)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[primitive.name];
      if (fn) fn(group, primitive.params);
    }
  }

  return group;
}
